import{_ as i,a0 as p,w as a,s as f,ao as l,I as r,x as s,a1 as o,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"Linux有問必答：如何擴展XFS文件系統 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：如何擴展XFS文件系統 | LCTT (201410) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：如何擴展XFS文件系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：如何擴展XFS文件系統 | LCTT (201410) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system","title":"Linux有問必答：如何擴展XFS文件系統","tag":"201410","desc":""},"relativePath":"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system.md","filePath":"[post].md"}'),x={name:"201410/20140915 Linux FAQs with Answers--How to expand an XFS file system.md"};function d(m,t,u,_,S,F){const e=p("Link");return a(),f("div",null,[t[11]||(t[11]=l(`<h1 id="linux有問必答-如何擴展xfs文件系統" tabindex="-1">Linux有問必答：如何擴展XFS文件系統 <a class="header-anchor" href="#linux有問必答-如何擴展xfs文件系統" aria-label="Permalink to “Linux有問必答：如何擴展XFS文件系統”">​</a></h1><blockquote><p><strong>問題</strong>：我的磁盤上有額外的空間，所以我想要擴展其上創建的現存的XFS文件系統，以完全使用額外空間。怎樣才是擴展XFS文件系統的正確途徑？</p></blockquote><p>XFS是一個開源的（GPL）日誌文件系統，最初由硅谷圖形（SGI）開發，現在大多數的Linux發行版都支持。事實上，XFS已被最新的CentOS/RHEL 7採用，成為其默認的文件系統。在其眾多的特性中，包含了“在線調整大小”這一特性，使得現存的XFS文件系統在已經掛載的情況下可以進行擴展。然而，對於XFS文件系統的<strong>縮減</strong>卻還沒有支持。</p><p>要擴展一個現存的XFS文件系統，你可以使用命令列工具xfs_growfs，這在大多數Linux發行版上都默認可用。由於XFS支持在線調整大小，目標文件系統可以掛在，也可以不掛載。</p><p>下面展示了<strong>xfs_growfs</strong>的基本用法：</p><p><img src="https://farm6.staticflickr.com/5551/14915082088_b4e29af3cf_z.jpg" alt=""></p><p>作為目標XFS文件系統來擴展，你可以指定掛載點、磁盤分區或者邏輯卷（在使用LVM時），使用數據塊數量來指定新的XFS文件系統的大小。你可以使用xfs_info命令列工具來檢查數據塊大小和數量：</p><p><img src="https://farm6.staticflickr.com/5584/14915075270_cd272d4468_z.jpg" alt=""></p><p>要將XFS文件擴展到1986208：</p><pre><code>$ sudo xfs_growfs /dev/centos/root -D 1986208
</code></pre><p>如果你不使用“-D”選項來指定大小，xfs_growfs將會自動擴展XFS文件系統到最大的可用大小。</p><pre><code>$ sudo xfs_growfs /dev/centos/root
</code></pre><p><img src="https://farm6.staticflickr.com/5569/14914950529_ddfb71c8dd_z.jpg" alt=""></p><p>注意，當你擴展一個現存的XFS文件系統時，必須準備好事先添加用於XFS文件系統擴展的空間。這雖然是很顯然的事，但是如果在所在的分區或磁盤捲上沒有空閒空間可用的話，xfs_growfs就沒有辦法了。同時，如果你嘗試擴展XFS文件系統大小到超過磁盤分區或卷的大小，xfs_growfs將會失敗。</p><p><img src="https://farm4.staticflickr.com/3870/15101281542_98a49a7c3a_z.jpg" alt=""></p><hr>`,16)),r("p",null,[t[1]||(t[1]=s("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/expand-xfs-file-system.html"},{default:n(()=>[...t[0]||(t[0]=[s("http://ask.xmodulo.com/expand-xfs-file-system.html",-1)])]),_:1})]),r("p",null,[t[4]||(t[4]=s("譯者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[2]||(t[2]=[s("GOLinux",-1)])]),_:1}),t[5]||(t[5]=s(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:n(()=>[...t[3]||(t[3]=[s("wxy",-1)])]),_:1})]),r("p",null,[t[8]||(t[8]=s("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[6]||(t[6]=[s("LCTT",-1)])]),_:1}),t[9]||(t[9]=s(" 原創翻譯，",-1)),o(e,{href:"http://linux.cn/"},{default:n(()=>[...t[7]||(t[7]=[s("Linux中國",-1)])]),_:1}),t[10]||(t[10]=s(" 榮譽推出",-1))])])}const w=i(x,[["render",d]]);export{L as __pageData,w as default};
